function voidCountForm(pick=''){const doc=raw().inventory,dates=[...new Set(A(doc.stocktakes).filter(s=>s.inventoryScope==='RAYO'&&s.status==='approved'&&s.baselineBoundary!=='START'&&!s.isOpeningBaseline).map(s=>E.D(s.date)))].sort().reverse();if(!dates.length)return P.toast('شمارش کل پایان روزی برای ابطال نیست','info');
 formModal({title:'حذف (ابطال) شمارش یک روز',ok:'ابطال روی سرور',can:canVoid,why:()=>'نیاز به دسترسی «ویرایش، ابطال و بازگردانی ثبت‌های انبار»',body:`${P.field('تاریخ شمارش',`<select class="select" name="d">${dates.map(d=>{const sel=d===pick?' selected':'';const n=A(doc.stocktakes).filter(s=>s.inventoryScope==='RAYO'&&s.status==='approved'&&E.D(s.date)===d&&s.baselineBoundary!=='START').reduce((a,s)=>a+A(s.lines).length,0);return`<option value="${d}"${sel}>${fa(d)} — ${fa(n)} قلم</option>`}).join('')}</select>`)}${P.field('علت *','<textarea class="textarea" name="reason" rows="2"></textarea>')}${P.note('شمارش حذف فیزیکی نمی‌شود و «باطل» می‌ماند؛ اقلام آن از شمارش قبلی خودشان ادامه می‌دهند و مغایرت شمارش‌های بعدی خودکار بازمحاسبه می‌شود. برای اصلاح چند قلم، همان تاریخ را دوباره بشمارید (جایگزین می‌شود). افتتاحیه از اینجا باطل نمی‌شود.','alert-triangle')}`,
  onSave:(m,btn)=>{const date=val(m,'d'),reason=val(m,'reason');if(!confirm(`شمارش ${fa(date)} باطل شود؟`))return;run(btn,{action:'WHOLE_STOCKTAKE_VOIDED',details:{date,reason},mutate:(d,c)=>W.voidCountDate(d,c,{date,reason}),done:o=>`شمارش ${fa(date)} (${fa(o.lines)} قلم) باطل شد`})}})}
