const lvB=l=>P.b(LVL[l]?.[1]||l,LVL[l]?.[0]||'neutral',1),pc=v=>v===null||v===undefined?'—':fa((Math.round(v*10)/10).toLocaleString('en-US'))+'٪',tm=v=>v===null||v===undefined?'—':fa(Math.round(v).toLocaleString('en-US'));
function cmReport(){const m=M(),keys=E.monthKeys(m);if(!cmS.month||!keys.includes(cmS.month))cmS.month=keys[keys.length-1];const r=E.monthRange(cmS.month),to=r.to>E.CAL.today?E.CAL.today:r.to,k=cmS.month+'|'+to+'|'+(raw().inventory?.meta?.serverSaveToken||'')+'|'+JSON.stringify(raw().inventory?.settings?.consumptionAlerts||{});
 if(cmS.key!==k){const Pd=E.analyze(m,r.from,to,{fixUnits:true});cmS.R={...CA().report(Pd,raw().inventory?.settings?.consumptionAlerts,{levelOf:id=>W.levelOf(raw().inventory,id)}),P:Pd,from:r.from,to};cmS.key=k}return{keys,R:cmS.R}}
function cmReal(){const {keys,R}=cmReport(),t=R.totals,s=R.settings,seg=[['items','وضعیت اقلام','list-checks'],['menu','اثر روی آیتم‌های منو','utensils'],['oil','روغن و اقلام سر میز','droplet']];
 const head=`<div class="row" style="gap:8px;flex-wrap:wrap;align-items:center;margin-bottom:var(--s3)"><select class="select" id="cmMonth" style="width:auto">${keys.slice().reverse().map(k=>`<option value="${k}" ${k===cmS.month?'selected':''}>${esc(E.monthLabel(k))}</option>`).join('')}</select><span class="muted">${fa(R.from)} تا ${fa(R.to)} · ${fa(R.P.days)} روز${R.P.coverage<0.999?` · <span class="neg">فروش ${fa(Math.round((1-R.P.coverage)*R.P.days))} روز ثبت نشده</span>`:''}</span><div class="grow"></div><div class="tabs">${seg.map(([k,l,i])=>`<a class="tab ${cmS.sub===k?'active':''}" href="#" data-cm-sub="${k}">${P.ic(i)}${l}</a>`).join('')}</div></div>`;
 if(cmS.sub==='oil')return srcLine()+head+oilReal(R);
 const kp=(icon,label,v,sub,cls='')=>`<div class="card kpi"><div class="kpi-head"><span class="kpi-icon">${P.ic(icon)}</span><span>${label}</span></div><div class="kpi-value ${cls}">${v}</div><div class="kpi-sub">${sub}</div></div>`;
 const kpis=`<div class="grid grid-4">${kp('receipt','فروش دوره',tm(t.sales),'تومان؛ فایل فروش آیتم‌ها')}${kp('trash-2','پرتی و ضایعات',tm(t.waste),`${pc(t.wasteSalesPct)} از فروش`)}${kp('scale','کسری توضیح‌داده‌نشده',tm(t.shortage),`${pc(t.varianceSalesPct)} از فروش؛ مازاد ${tm(t.surplus)} کم نمی‌کند`)}${kp('gauge','مجموع اتلاف از فروش',pc(t.lossSalesPct),`${lvB(t.level)} مرز ${pc(s.lossSalesWarn)} / ${pc(s.lossSalesCritical)}`,t.level==='critical'?'neg':'')}</div>`;
 const note=!R.alertWindow?P.note(`دوره کوتاه‌تر از «حداقل روز دوره برای هشدار» (${fa(s.minDays)} روز) است؛ وضعیت‌ها «داده ناکافی» نشان داده می‌شوند.`,'info'):'';
 let body;
 if(cmS.sub==='menu'){const ml=R.menus.list.filter(x=>x.revenue>0||x.theoretical>0),mn=id=>M().menu.get(id)?.name||id;
  body=P.card({title:'اثر پرتی و کسری روی آیتم‌های منو',sub:'سهم هر آیتم از پرتی و کسری هر ماده به نسبت مصرف رسپی همان آیتم در این دوره (تخمینی)'+(R.menus.unallocated>1?`؛ ${tm(R.menus.unallocated)} تومان اتلاف موادی که در رسپی فروش این دوره نبودند تخصیص نیافت`:''),flush:1,
   body:P.table(['آیتم منو',{t:'تعداد',n:1},{t:'فروش',n:1},{t:'٪ بهای رسپی',n:1},{t:'سهم پرتی',n:1},{t:'سهم کسری',n:1},{t:'٪ بهای واقعی',n:1},{t:'اثر اتلاف',n:1},'وضعیت'],ml.map(x=>[esc(mn(x.menuId)),fa(Math.round(x.qty)),tm(x.revenue),pc(x.costPct),tm(x.wasteShare),tm(x.shortageShare),`<span class="${x.adjustedPct>s.targetMaterialCostPercent?'neg':''}">${pc(x.adjustedPct)}</span>`,pc(x.lossImpact),lvB(x.level)]),{empty:'فروش آیتم‌ها در این دوره ثبت نشده است'})+`<p class="muted" style="padding:8px var(--s4)">هدف بهای مواد: ${pc(s.targetMaterialCostPercent)}؛ «٪ بهای واقعی» = (بهای رسپی + سهم پرتی + سهم کسری) ÷ فروش آیتم.</p>`})}
 else{const q=cmS.q,rows=R.rows.filter(r=>(cmS.all||['warning','critical'].includes(r.status))&&(!q||P.match(r.name+' '+r.code+' '+r.category,q))).sort((a,b)=>(({critical:0,warning:1,ok:2,na:3})[a.status]-({critical:0,warning:1,ok:2,na:3})[b.status])||((b.waste+b.shortage)-(a.waste+a.shortage)));
  body=P.card({title:'وضعیت مصرف اقلام',sub:`بحرانی ${fa(t.counts.critical)} · نیازمند بررسی ${fa(t.counts.warning)} · عادی ${fa(t.counts.ok)} · داده ناکافی ${fa(t.counts.na)}`,actions:`<input class="input" id="cmQ" value="${esc(q)}" placeholder="جستجو" style="width:160px"><label class="check"><input type="checkbox" id="cmAll" ${cmS.all?'checked':''}>همهٔ اقلام</label>`,flush:1,
   body:P.table(['کالا','گروه',{t:'مصرف واقعی',n:1},{t:'مصرف رسپی',n:1},{t:'پرتی',n:1},{t:'٪ پرتی',n:1},{t:'کسری',n:1},{t:'٪ مغایرت',n:1},'وضعیت','توضیح'],rows.slice(0,300).map(r=>[P.cellMain(esc(r.name),esc(r.code)),esc(r.category),tm(r.actual),tm(r.theoretical),tm(r.waste),`<span title="مرز ${esc(pc(r.thresholds.wasteWarn))} / ${esc(pc(r.thresholds.wasteCritical))}">${pc(r.wastePct)}</span>`,tm(r.shortage),`<span title="مرز ${esc(pc(r.thresholds.varianceWarn))} / ${esc(pc(r.thresholds.varianceCritical))}">${pc(r.variancePct)}</span>`,lvB(r.status),`<small class="muted">${esc([...r.reasons,r.thresholds.source==='ingredient'?'آستانهٔ اختصاصی کالا':r.thresholds.source==='category'?'آستانهٔ گروه':''].filter(Boolean).join('؛ '))}</small>`]),{empty:cmS.all?'قلمی در این دوره گردش ندارد':'قلمی در وضعیت هشدار نیست؛ «همهٔ اقلام» را بزنید'})+`<p class="muted" style="padding:8px var(--s4)">٪ پرتی = ارزش پرتی ÷ ارزش مصرف واقعی؛ ٪ مغایرت = کسری توضیح‌داده‌نشده ÷ مصرف رسپی. مرزها در «تنظیمات» انبار.</p>`})}
 return srcLine()+head+kpis+note+'<div class="mt">'+body+'</div>'}
